/**
 * permitGenerator.js
 *
 * Generates a PERMIT PREPARATION SUMMARY document.
 *
 * IMPORTANT:
 * This document is NOT an official business permit.
 * It is generated by PermitEase for preparation purposes only.
 * It does not constitute permit approval, issuance, or authorization to operate.
 *
 * The official permit must be obtained from the Municipality of Roxas, Oriental Mindoro / BPLO.
 */

const PDFDocument = require('pdfkit');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

// Ensure output directory exists
const PERMITS_DIR = path.join(__dirname, '../../uploads/permits');
const TEMP_DIR = path.join(__dirname, '../../uploads/temp');

if (!fs.existsSync(PERMITS_DIR)) fs.mkdirSync(PERMITS_DIR, { recursive: true });
if (!fs.existsSync(TEMP_DIR)) fs.mkdirSync(TEMP_DIR, { recursive: true });

/**
 * Generate a PermitEase internal reference code (NOT an official permit number).
 * This is only used as a file identifier, not displayed as a permit number.
 */
const generateInternalRefCode = () => {
    return `PE-REF-${crypto.randomBytes(5).toString('hex').toUpperCase()}`;
};

/**
 * Generate a Permit Preparation Summary PDF.
 * This document is clearly labeled as a preparation tool — not an official permit.
 *
 * @param {Object} data - Business and preparation data
 * @returns {Promise<string>} - Path to the temporary PDF file
 */
const generatePermitDocument = async (data) => {
    return new Promise((resolve, reject) => {
        try {
            const {
                business_name,
                owner_name,
                business_type,
                industry_category,
                address,
                permit_type,
                assessment_date,
                checklist = [],
                estimated_fees = null
            } = data;

            const tempFileName = `prep_summary_${crypto.randomBytes(4).toString('hex')}.pdf`;
            const tempFilePath = path.join(TEMP_DIR, tempFileName);

            const doc = new PDFDocument({ size: 'A4', margin: 50 });
            const stream = fs.createWriteStream(tempFilePath);
            doc.pipe(stream);

            // ────────────────────────────────────────────────
            // HEADER — System identity, NOT government seal
            // ────────────────────────────────────────────────
            doc.font('Helvetica-Bold').fontSize(10).fillColor('#166534')
               .text('PermitEase — Business Permit Preparation Support System', { align: 'center' });
            doc.font('Helvetica').fontSize(9).fillColor('#64748B')
               .text('Municipality of Roxas, Oriental Mindoro', { align: 'center' });

            doc.moveDown(0.5);

            // Title
            doc.font('Helvetica-Bold').fontSize(18).fillColor('#1E3A5F')
               .text('PERMIT PREPARATION SUMMARY', { align: 'center' });

            doc.font('Helvetica').fontSize(9).fillColor('#64748B')
               .text('For preparation and pre-assessment purposes only — Not an official business permit.', { align: 'center' });

            doc.moveDown(1);

            // ────────────────────────────────────────────────
            // DISCLAIMER BOX
            // ────────────────────────────────────────────────
            const disclaimerY = doc.y;
            doc.rect(50, disclaimerY, 495, 55).fillColor('#FEF9C3').fill();
            doc.rect(50, disclaimerY, 495, 55).strokeColor('#CA8A04').stroke();
            doc.fillColor('#713F12').font('Helvetica-Bold').fontSize(8)
               .text('IMPORTANT NOTICE', 60, disclaimerY + 6);
            doc.font('Helvetica').fontSize(8)
               .text(
                   'This document is generated by PermitEase for preparation purposes only. It is NOT an official business permit and does NOT constitute permit approval, issuance, or authorization to operate. Final requirements, official assessment, fees, signatures, payment, and permit processing are subject to the official process of the Municipality of Roxas, Oriental Mindoro / BPLO.',
                   60, disclaimerY + 18,
                   { width: 475, lineGap: 2 }
               );
            doc.y = disclaimerY + 65;
            doc.fillColor('black');

            doc.moveDown(0.5);

            // ────────────────────────────────────────────────
            // BUSINESS INFORMATION
            // ────────────────────────────────────────────────
            doc.font('Helvetica-Bold').fontSize(11).fillColor('#1E3A5F')
               .text('Business Information');
            doc.moveTo(50, doc.y).lineTo(545, doc.y).strokeColor('#CBD5E1').stroke();
            doc.moveDown(0.3);

            const infoRows = [
                ['Business Name', business_name || '—'],
                ['Owner / Operator', owner_name || '—'],
                ['Business Type', business_type || '—'],
                ['Industry Category', industry_category || '—'],
                ['Address', address || '—'],
                ['Application Type', permit_type === 'NEW' ? 'New Business Permit Application' : 'Renewal'],
                ['Preparation Date', assessment_date || new Date().toLocaleDateString('en-PH', { year: 'numeric', month: 'long', day: 'numeric' })]
            ];

            doc.font('Helvetica').fontSize(9).fillColor('#1E293B');
            for (const [label, value] of infoRows) {
                const rowY = doc.y;
                doc.font('Helvetica-Bold').text(label + ':', 55, rowY, { width: 140, continued: false });
                doc.font('Helvetica').text(value, 200, rowY, { width: 340 });
                doc.moveDown(0.35);
            }

            doc.moveDown(0.5);

            // ────────────────────────────────────────────────
            // PREPARATION CHECKLIST (if provided)
            // ────────────────────────────────────────────────
            if (checklist.length > 0) {
                doc.font('Helvetica-Bold').fontSize(11).fillColor('#1E3A5F')
                   .text('Preparation Checklist');
                doc.moveTo(50, doc.y).lineTo(545, doc.y).strokeColor('#CBD5E1').stroke();
                doc.moveDown(0.3);

                doc.font('Helvetica').fontSize(9).fillColor('#1E293B');
                for (const item of checklist) {
                    const statusIcon = (item.status === 'Submitted' || item.status === 'Approved') ? '[READY]' : '[NEEDED]';
                    const statusColor = (item.status === 'Submitted' || item.status === 'Approved') ? '#166534' : '#9A3412';
                    const rowY = doc.y;
                    doc.fillColor(statusColor).font('Helvetica-Bold').text(statusIcon, 55, rowY, { width: 70 });
                    doc.fillColor('#1E293B').font('Helvetica').text(item.permit_name || item.name || '—', 130, rowY, { width: 415 });
                    doc.moveDown(0.35);
                }
                doc.moveDown(0.5);
            }

            // ────────────────────────────────────────────────
            // ESTIMATED FEES (if provided)
            // ────────────────────────────────────────────────
            if (estimated_fees) {
                doc.font('Helvetica-Bold').fontSize(11).fillColor('#1E3A5F')
                   .text('Estimated Fees (Pre-Assessment Only)');
                doc.moveTo(50, doc.y).lineTo(545, doc.y).strokeColor('#CBD5E1').stroke();
                doc.moveDown(0.3);

                doc.font('Helvetica').fontSize(8).fillColor('#64748B')
                   .text('These are estimates based on configured rules. Actual amounts will be determined by the BPLO during official assessment.');
                doc.moveDown(0.3);

                if (estimated_fees.total_estimated_amount != null) {
                    doc.font('Helvetica-Bold').fontSize(10).fillColor('#1E3A5F')
                       .text(`Estimated Total: PHP ${Number(estimated_fees.total_estimated_amount).toLocaleString('en-PH', { minimumFractionDigits: 2 })}`, { align: 'right' });
                } else {
                    doc.font('Helvetica').fontSize(9).fillColor('#9A3412')
                       .text('Estimated total unavailable — official assessment required.', { align: 'right' });
                }
                doc.moveDown(0.5);
            }

            // ────────────────────────────────────────────────
            // FOOTER
            // ────────────────────────────────────────────────
            const footerY = doc.page.height - 80;
            doc.moveTo(50, footerY).lineTo(545, footerY).strokeColor('#CBD5E1').stroke();
            doc.font('Helvetica').fontSize(7.5).fillColor('#94A3B8')
               .text(
                   'This document was generated by PermitEase, a Business Permit Preparation and Compliance Support System for the Municipality of Roxas, Oriental Mindoro. PermitEase does not issue, approve, or process official business permits. For official permit processing, please visit the BPLO office of the Municipality of Roxas.',
                   50, footerY + 8,
                   { width: 495, align: 'center', lineGap: 2 }
               );

            doc.end();

            stream.on('finish', () => resolve(tempFilePath));
            stream.on('error', (err) => reject(err));
        } catch (error) {
            reject(error);
        }
    });
};

/**
 * Move temp file to final destination.
 * Uses an internal reference code as filename (NOT an official permit number).
 */
const finalizePermitDocument = (tempPath, internalRef) => {
    const finalFileName = `prep_summary_${internalRef}_${Date.now()}.pdf`;
    const finalPath = path.join(PERMITS_DIR, finalFileName);
    fs.renameSync(tempPath, finalPath);
    return `permits/${finalFileName}`;
};

/**
 * Cleanup temp file
 */
const cleanupTempFile = (tempPath) => {
    if (tempPath && fs.existsSync(tempPath)) {
        try { fs.unlinkSync(tempPath); } catch (e) {
            console.error('Failed to cleanup temp file:', e);
        }
    }
};

/**
 * Kept for backward compatibility with applicationController.js
 * Returns an internal reference code — NOT an official permit number.
 */
const generateVerificationCode = () => {
    return generateInternalRefCode();
};

module.exports = {
    generateVerificationCode,
    generateInternalRefCode,
    generatePermitDocument,
    finalizePermitDocument,
    cleanupTempFile
};
